<?php

namespace App\Tailoring;

?>
<?php require __DIR__.'/marketing/'.$GLOBALS['locale'].'/services-top.php'; ?>
<section id="catalogue" class="catalogue-section"><div class="catalogue-heading"><div><p class="section-label"><?= t('FIND YOUR NEXT FIT')?></p><h2><?= t('The tailoring edit.')?></h2></div><p><?= t('Clear prices. Personal fit. Care in every stitch.')?></p></div><div class="catalogue-toolbar"><nav class="category-filters" aria-label="<?= t('Service categories')?>">
<?php foreach (['ALL' => 'All services'] + CATEGORIES as $code => $label) {
    $count = $code === 'ALL' ? count($all) : count(array_filter($all, fn ($s) => $s['category'] === $code));
    if (! $count && $code !== 'ALL') {
        continue;
    } ?><a class="category-chip <?= $category === $code ? 'is-selected' : ''?>" <?= $category === $code ? 'aria-current="true"' : ''?> href="/services?<?= e(http_build_query(['category' => $code, 'q' => $search]))?>#catalogue"><?= t($label)?> <span><?= $count?></span></a><?php } ?></nav><form class="catalogue-search" method="get" action="/services#catalogue"><input type="hidden" name="category" value="<?= e($category)?>"><label class="visually-hidden" for="service-search"><?= t('Search services')?></label><input type="search" id="service-search" name="q" value="<?= e($search)?>" maxlength="80" placeholder="<?= t('Search services')?>"><button type="submit" aria-label="<?= t('Search services')?>">⌕</button></form></div><div class="catalogue-results"><span><?= count($services)?> <?= t('Services')?></span><a href="/services#catalogue"><?= t('Clear filters')?> ×</a></div>
<div class="service-grid"><?php foreach ($services as $s) {
    $name = $GLOBALS['locale'] === 'hi' && $s['name_hi'] ? $s['name_hi'] : $s['name_en']; ?><article class="catalogue-card" data-service="<?= e($s['code'])?>"><div class="catalogue-photo"><?php if (isset(PHOTOS[$s['code']])) { ?><?= product_image(PHOTOS[$s['code']], $name)?><?php } else { ?><div class="service-placeholder"><img src="/static/img/brand-star.svg" alt="" width="80" height="80"></div><?php } ?><span class="service-category"><?= t(CATEGORIES[$s['category']])?></span></div><div class="catalogue-card-body"><p class="service-caption"><?= t('TAILORED TO YOU')?></p><h3><?= e($name)?></h3><p class="service-description"><?= e($s['description'] ?: raw_t('Cut to your measurements. Finished with care.'))?></p><div class="service-price-row"><div><?php if ($s['default_stitching_price'] !== null) { ?><strong class="service-price"><?= money($s['default_stitching_price'])?></strong><small><?= t('Stitching only')?></small><?php } else { ?><strong class="service-price service-quote"><?= t('Let’s talk fit.')?></strong><small><?= t('Please call for pricing')?></small><?php } ?></div><a class="service-action" href="<?= $s['default_stitching_price'] !== null ? '/order?service='.(int) $s['id'] : 'tel:+91'.e(SHOP_PHONE)?>"><?= t($s['default_stitching_price'] !== null ? 'Order online' : 'Call the shop')?> ↗</a></div></div></article><?php } ?>
<?php if (! $services) { ?><div class="catalogue-empty"><h3><?= t('No matching services')?></h3><p><?= t('Try another search or explore the full collection.')?></p><a class="btn btn-primary" href="/services#catalogue"><?= t('All services')?></a></div><?php } ?></div><p class="catalogue-disclaimer"><?= t('Stitching charges only — cloth is billed separately, whether you bring your own or the shop provides it.')?></p></section>
<?php require __DIR__.'/marketing/'.$GLOBALS['locale'].'/services-bottom.php'; ?>
